/**
 * The portrait as a static halftone: the whole hero visual on phones, tablets, low-end
 * GPUs and reduced motion, and what the WebGL portrait crossfades in over on desktop.
 *
 * Zero JavaScript and no <img>: the stipple is a white-on-transparent PNG used as a CSS
 * mask over the theme's ink, so it is always the right color for the theme and only the
 * active theme's file is downloaded. Placement mirrors PORTRAIT_VIEW (see globals.css).
 * Generated by scripts/build-portrait.mjs from the same field the 3D points sample.
 */
export function PortraitFallback() {
  return (
    <div className="portrait-stage" aria-hidden="true">
      <div className="portrait-fallback">
        <div className="portrait-halftone" />
      </div>
    </div>
  );
}
